    known[N_A as usize] = true;
    known[N_INPUT as usize] = true;
    known[N_TR1_BI as usize] = true;
    known[N_TR2_BI as usize] = true;
    known[N_TR3_BI as usize] = true;

    let mut urow = [-1i32; NUM_NODES];
